// Writes src-tauri/resources/licenses/DEPENDENCIES.txt: every Rust crate and npm package
// compiled into CaptionNest, with version and license.
// Usage: node scripts/licenses/collect.mjs
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const root = new URL("../../", import.meta.url).pathname;
const lines = [
  "CaptionNest — third-party packages compiled into the app",
  "Generated by scripts/licenses/collect.mjs. The MIT, Apache-2.0, LGPL-2.1 and OFL-1.1",
  "texts are in this folder; the license texts and copyright notices that other licenses",
  "(BSD, ISC, Zlib, MPL-2.0, Unicode, OFL fonts) require are in THIRD_PARTY_LICENSES.txt.",
  "",
];

// Rust: packages reachable from the app crate through normal (non-dev) dependencies.
const meta = JSON.parse(
  execFileSync("cargo", ["metadata", "--format-version", "1", "--manifest-path", join(root, "src-tauri/Cargo.toml")], {
    maxBuffer: 256 * 1024 * 1024,
  }).toString(),
);
const byId = new Map(meta.packages.map((p) => [p.id, p]));
const nodes = new Map(meta.resolve.nodes.map((n) => [n.id, n]));
const rootId = meta.resolve.root;
const seen = new Set();
const stack = [rootId];
while (stack.length) {
  const id = stack.pop();
  if (seen.has(id)) continue;
  seen.add(id);
  for (const dep of nodes.get(id)?.deps ?? []) {
    if (dep.dep_kinds.some((k) => k.kind === null || k.kind === "build")) stack.push(dep.pkg);
  }
}
const crates = [...seen].filter((id) => id !== rootId).map((id) => byId.get(id)).sort((a, b) => a.name.localeCompare(b.name));
lines.push(`Rust crates (${crates.length})`, "-".repeat(40));
for (const c of crates) lines.push(`${c.name} ${c.version} — ${c.license ?? "see " + (c.license_file ?? "package")}`);

// npm: production dependencies bundled into the interface.
const lock = JSON.parse(readFileSync(join(root, "package-lock.json"), "utf8"));
const npm = Object.entries(lock.packages)
  .filter(([path, p]) => path.startsWith("node_modules/") && !p.dev && !p.optional)
  .map(([path, p]) => {
    const pkgFile = join(root, path, "package.json");
    const pkg = existsSync(pkgFile) ? JSON.parse(readFileSync(pkgFile, "utf8")) : {};
    return { name: path.replace(/^.*node_modules\//, ""), version: p.version, license: p.license ?? pkg.license ?? "see package" };
  })
  .sort((a, b) => a.name.localeCompare(b.name));
lines.push("", `JavaScript packages (${npm.length})`, "-".repeat(40));
for (const p of npm) lines.push(`${p.name} ${p.version} — ${p.license}`);

const out = join(root, "src-tauri/resources/licenses/DEPENDENCIES.txt");
writeFileSync(out, lines.join("\n") + "\n");
console.log(`wrote ${out}: ${crates.length} crates, ${npm.length} npm packages`);

// License texts that must travel with the app: BSD-style, ISC, Zlib, Unicode and OFL
// licenses require each package's own copyright notice, and MPL-2.0 a pointer to the
// source. MIT/Apache texts are in the folder already (LICENSE files of those packages
// are included too when a package also names one of the licenses below).
const NEEDS_TEXT = /BSD-2-Clause|BSD-3-Clause|ISC|Zlib|MPL-2\.0|Unicode-3\.0|Unicode-DFS|OFL-1\.1/;
const LICENSE_FILE = /^(licen[cs]e|copying|notice)/i;
const textsOf = (dir) =>
  (existsSync(dir) ? readdirSync(dir) : [])
    .filter((f) => LICENSE_FILE.test(f) && statSync(join(dir, f)).isFile())
    .sort()
    .map((f) => ({ file: f, text: readFileSync(join(dir, f), "utf8").trim() }));

const notices = [
  "CaptionNest — license texts and copyright notices of bundled third-party code",
  "Generated by scripts/licenses/collect.mjs.",
  "",
];
// "Zlib OR Apache-2.0 OR MIT": the MIT/Apache terms (whose texts ship) can be chosen.
const hasMitOrApacheChoice = (lic) => /\bOR\b|\//.test(lic) && /\b(MIT|Apache-2\.0)\b/.test(lic) && !/\bAND\b/.test(lic);
const section = (title, source, texts, lic = "") => {
  if (texts.length === 0) {
    if (!lic || hasMitOrApacheChoice(lic)) return;
    // No license file in the package: name the license and where the source is.
    texts = [{ file: "note", text: `Licensed under ${lic}. The package has no license file; its text is at the source below.` }];
  }
  notices.push("=".repeat(78), title, ...(source ? [`Source: ${source}`] : []), "=".repeat(78), "");
  for (const t of texts) notices.push(`--- ${t.file} ---`, t.text, "");
};

for (const c of crates) {
  if (!NEEDS_TEXT.test(c.license ?? "")) continue;
  const texts = textsOf(dirname(c.manifest_path));
  const needsSource = /MPL-2\.0/.test(c.license) || texts.length === 0;
  section(`${c.name} ${c.version} (${c.license})`, needsSource ? `https://crates.io/crates/${c.name}/${c.version}` : null, texts, c.license);
}

// SentencePiece is compiled from source with its own bundled libraries.
const spm = crates.find((c) => c.name === "sentencepiece-sys");
if (spm) {
  const src = join(dirname(spm.manifest_path), "source");
  section(`SentencePiece (Apache-2.0), in ${spm.name} ${spm.version}`, null, textsOf(src));
  const third = join(src, "third_party");
  const libs = existsSync(third) ? readdirSync(third).filter((d) => statSync(join(third, d)).isDirectory()) : [];
  for (const lib of libs.sort()) {
    section(`${lib} (bundled in SentencePiece)`, null, textsOf(join(third, lib)));
  }
}

for (const p of npm) {
  if (!NEEDS_TEXT.test(p.license ?? "")) continue;
  section(`${p.name} ${p.version} (${p.license})`, null, textsOf(join(root, "node_modules", p.name)));
}

const noticesOut = join(root, "src-tauri/resources/licenses/THIRD_PARTY_LICENSES.txt");
writeFileSync(noticesOut, notices.join("\n") + "\n");
console.log(`wrote ${noticesOut}`);
